const listBuildings = `-- name: ListBuildings :many
SELECT b.id, b.site_id, b.code, b.name, b.notes, b.version, b.created_at, b.updated_at, b.archived_at, s.code AS site_code, s.name AS site_name, count(*) OVER () AS total
FROM buildings b JOIN sites s ON s.id = b.site_id
WHERE ($1::bool OR b.site_id = ANY($2::uuid[]))
  AND ($3::bool OR b.archived_at IS NULL)
  AND ($4::uuid IS NULL OR b.site_id = $4)
  AND ($5::text = '' OR b.name ILIKE '%' || $5 || '%' ESCAPE '\' OR b.code ILIKE '%' || $5 || '%' ESCAPE '\')
ORDER BY
  CASE WHEN $6::text = '-name' THEN lower(b.name) END DESC,
  CASE WHEN $6::text = 'updated_at' THEN b.updated_at END ASC,
  CASE WHEN $6::text = '-updated_at' THEN b.updated_at END DESC,
  s.code ASC, lower(b.name) ASC
LIMIT $8 OFFSET $7
`

