func (q *Queries) ListBuildings(ctx context.Context, arg ListBuildingsParams) ([]ListBuildingsRow, error) {
	rows, err := q.db.Query(ctx, listBuildings,
		arg.AllSites,
		arg.SiteIds,
		arg.IncludeArchived,
		arg.SiteID,
		arg.Query,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListBuildingsRow
	for rows.Next() {
		var i ListBuildingsRow
		if err := rows.Scan(
			&i.ID,
			&i.SiteID,
			&i.Code,
			&i.Name,
			&i.Notes,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
			&i.SiteCode,
			&i.SiteName,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

