// Facility hierarchy (v0.4.1, D-082..D-085). Every query takes the caller's site scope (authz.Scope):
//
//	(@all_sites::bool OR site_id = ANY(@site_ids::uuid[]))
//
// There are no unscoped variants: rows outside the scope behave exactly like missing rows (404).
// Updates and archiving require the expected version (optimistic lock); no row back = missing or stale.
// ---------------------------------------------------------------------------------------------------------------
// Sites
func (q *Queries) ListSites(ctx context.Context, arg ListSitesParams) ([]ListSitesRow, error) {
	rows, err := q.db.Query(ctx, listSites,
		arg.AllSites,
		arg.SiteIds,
		arg.IncludeArchived,
		arg.Status,
		arg.Query,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSitesRow
	for rows.Next() {
		var i ListSitesRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.Address,
			&i.Status,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

